INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (1, 'en', 'Control script steps', 'Control script steps control the progression of the script by letting you tell FileMaker Pro exactly what to do when and if specific conditions occur.', 2);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (2, 'en', 'Navigation script steps', 'Navigation script steps move to different areas of a database.', 3);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (3, 'en', 'Editing script steps', 'With editing script steps, you can cut, copy, paste, or clear the contents of a field; undo or redo previous actions; or select the contents of a field.', 4);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (4, 'en', 'Fields script steps', 'Fields script steps operate on specific fields, or in some cases, variables.', 5);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (5, 'en', 'Records script steps', 'Records script steps affect specific records and find requests.', 6);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (6, 'en', 'Found Sets script steps', 'Found Sets script steps let you find records and work with found sets.', 7);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (7, 'en', 'Windows script steps', 'Windows script steps affect screen elements and windows.', 8);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (8, 'en', 'Files script steps', 'Files script steps operate on entire files. Some operate only on FileMaker Pro files, only on data files, or on any file.', 9);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (9, 'en', 'Accounts script steps', 'Accounts script steps allow you to create and manage accounts.', 10);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (10, 'en', 'Artificial intelligence script steps', 'Artificial intelligence (AI) script steps allow you to work with large language models (LLMs) and Core ML models.', 11);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (11, 'en', 'Spelling script steps', 'Spelling script steps let you perform spell checking tasks.', 12);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (12, 'en', 'PDF files script steps', 'PDF files script steps create, modify, and print PDF documents. Use these script steps to build workflows that combine data and pages from multiple sources into PDF documents.', 13);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (13, 'en', 'Open Menu Item script steps', 'Open Menu Item script steps open specific FileMaker Pro dialog boxes as if you had chosen the command from a menu. You could use one of these script steps to open a dialog box for users if you have restricted their access to FileMaker Pro menus with access privileges.', 14);
INSERT INTO "script_step_category_localizations" ("category_id", "locale", "name", "description", "help_page_id") VALUES (14, 'en', 'Miscellaneous script steps', 'Miscellaneous script steps allow you to script miscellaneous actions.', 15);
